ANNOTATIONS = [
    (48, 'after', r'''文件级：@ 文件补全的索引层，useTypeahead 的地基。模块级状态一份：FileIndex 单例（Rust nucleo 模糊搜索引擎）、刷新 Promise、构建完成信号、cacheGeneration（清缓存守卫）、tracked/config/dirs 三份缓存、ignore 模式缓存、节流状态、两份加载签名。'''),
    (99, 'after', r'''clearFileSuggestionCaches：resume 会话时全清——文件发现必须重新来一遍，不能沿用上个 session 的索引。清 signal 也要做（订阅者持有的完成通知作废）。'''),
    (131, 'after', r'''pathListSignature：路径列表的内容指纹。为什么不用 length|first|last 采样——中间文件重命名时长度和端点都不变，陈旧条目会永久卡在 nucleo 里。改成每 500 个采一个 + 显式把最后一个路径并进去（单文件增删在尾部能被抓到），346k 路径只哈希 ~700 个，<1ms。采样间隙漏掉的中部单文件重命名靠 5s 刷新地板兜底。'''),
    (147, 'after', r'''getGitIndexMtime：stat .git/index 检测 git 状态变化，不用每次击键都起 git ls-files。三种情况返回 null 让调用方回退时间节流：worktree（.git 是文件 → ENOTDIR）、新仓库还没 index（ENOENT）、非 git 目录。eslint-disable 注释解释了为什么这里刻意用同步 stat：mtimeMs 就是操作本身，上面 findGitRoot 已经同步 stat 走过一遍，异步反而会破坏 fileListRefreshPromise 的同步冷启动契约。'''),
    (164, 'after', r'''normalizeGitPaths：git ls-files 在 repoRoot 下跑、输出相对 repoRoot，而补全要相对 cwd——两者不同时全部重算。相同（cwd 就是根）时零拷贝返回。'''),
    (195, 'after', r'''mergeUntrackedIntoNormalizedCache：未跟踪文件后台合入。三道守卫：空列表、无索引、tracked 空。合并签名（loadedMergedSignature）与 tracked 签名分开——两个 loadFromFileList 调用点的数组结构不同，共用签名会乒乓永远不命中。'''),
    (238, 'after', r'''loadRipgrepIgnorePatterns：.ignore/.rgignore 是 ripgrep 专属的，git ls-files 不认识——所以 tracked 文件也要过一遍这个过滤器才能和 ripgrep 兜底路径的结果一致。按 repoRoot:cwd 缓存。'''),
    (283, 'after', r'''getFilesUsingGit 的两个要点：① core.quotepath=false——git 默认把非 ASCII 路径转义成八进制，中文文件名会变乱码；② tracked 立即返回（读 index 快），untracked 后台拉（--others，可选 --exclude-standard 尊重 gitignore）。'''),
    (332, 'after', r'''generation 守卫：untracked 后台拉取期间缓存被清（resume），旧代结果不合入——陈旧文件不会污染新索引。'''),
    (378, 'after', r'''tracked 路径同步返回，untracked 的 merge 是 void 异步——补全先能用（tracked 部分），完整列表随后到位。注释还说明与 ripgrep --follow 的差异：git 把 symlink 当 symlink 跟踪，不跟随，这是有意的。'''),
    (440, 'after', r'''collectDirectoryNames 的早退设计：path.dirname 在根目录返回自身（不动点），所以循环到 dirname 不再变化就停；先查 out.has 再 add 把根挡在结果外——省掉每文件一次的 path.parse()（那会分配五字段对象）。目录列表让补全能提示 src/ 这样的路径片段。'''),
    (516, 'after', r'''getProjectFiles：git 优先、ripgrep 兜底。ripgrep 参数 --follow（跟随 symlink）+ --hidden（含点文件）+ 六种 VCS 目录排除（.git/.svn/.hg/.bzr/.jj/.sl，jj 是 jujutsu）；respectGitignore=false 时才加 --no-ignore-vcs。'''),
    (570, 'after', r'''getPathsForSuggestions：respectGitignore 的优先级是项目设置 > 全局配置 > 默认 true。签名相同就跳过重建（打字期间的常见情况——ls-files 输出不变）；重建后把 loadedMergedSignature 置 null 强制下次合并重建（刚用 tracked-only 覆盖过合并索引，不强制的话合并签名还「匹配」着旧数据）。'''),
    (598, 'after', r'''findLongestCommonPrefix：Tab 渐进补全的依据——所有建议的公共前缀比已输入长才替换。'''),
    (626, 'after', r'''MAX_SUGGESTIONS=15：补全列表上限。findMatchingFiles 直接打 nucleo 索引的 search，score 进 metadata 备调试。'''),
    (686, 'after', r'''startBackgroundCacheRefresh 的节流设计（注释写得很细）：有缓存才节流，冷启动必须填充；.git/index mtime 变了立即刷（add/checkout/commit/rm 都动它）；否则最多 5s 一次——这个地板专捡未跟踪文件（它们不动 .git/index）。刷新期间索引是渐进可查的（readyCount），早到的搜索拿部分结果，构建完成后 indexBuildComplete 信号触发重搜。成功路径才提交 mtime 观察值——刷新中途 git 又变了，下次调用看到新 mtime 会再刷。'''),
    (708, 'after', r'''getTopLevelPaths：空查询（或 ./）时列当前目录——用户打 @ 第一下看到的就是这层。'''),
    (784, 'after', r'''generateFileSuggestions 的四条路径：① 自定义 command 优先——用户配了 fileSuggestion command 就全权交给它，不混 config 文件（命令用自己的排序逻辑返回预排结果）；② 空/点查询 → 顶层目录列表并踢一次后台刷新；③ 正常查询——先踢刷新（部分结果立即可用），处理 ./ 与 .\ 两种前缀、~ 家目录展开，然后查索引；④ 任何异常吞掉返回空（补全不该炸输入）。遥测区分 cache_hit（刷新是否在进行中）。'''),
    (811, 'after', r'''applyFileSuggestion：替换 token 并把光标移到路径末尾。accepts 字符串（公共前缀场景）或 SuggestionItem（选中场景）两种形态。'''),
]
